script:
// Maple Grove v18 - life-size suburb. Every house has a working front door.
var HOUSES = [[-156,-123],[-96,-123],[-36,-123],[24,-123],[84,-123],[144,-123],[-144,123],[-84,123],[-24,123],[36,123],[96,123],[156,123],[-143,-44],[-143,6],[-143,56],[143,-56],[143,-6],[143,44],[97,-39],[97,51]];
var SPOTS = { park: [0, 60], spawn: [0, 70], store: [-99, -46], court: [-80, 45], pond: [-22, 50], swings: [24, -48] };

Game.on('join', function (name) { Game.toast(name + ' moved into Maple Grove'); });

// admin broadcasts: receivers check the sender really is an admin
Game.onNet('announce', function (d, from) {
  if (!Game.isAdmin(from) || !d || typeof d.t !== 'string') return;
  Game.banner(d.t.slice(0, 120));
});
Game.onNet('doors', function (d, from) {
  if (!Game.isAdmin(from) || !d) return;
  if (Game.setDoors(d.m)) Game.toast('Doors: ' + d.m);
});
Game.onNet('time', function (d, from) {
  if (!Game.isAdmin(from) || !d || !isFinite(d.h)) return;
  Game.setTime(+d.h);
});
function party() { Game.setTime(20); Game.setDoors('open'); Game.banner('BLOCK PARTY! Every door in Maple Grove is open.'); }
Game.onNet('party', function (d, from) { if (Game.isAdmin(from)) party(); });

// ---------- WORLD ADMIN COMMANDS (chat, admins only) ----------
Game.on('cmd', function (text) {
  if (text.charAt(0) !== '/') return false;
  var p = text.slice(1).split(/\s+/);
  var c = (p[0] || '').toLowerCase();
  var known = ['help', 'tp', 'time', 'doors', 'party', 'announce', 'heal'];
  if (known.indexOf(c) < 0) return false;
  if (!Game.isAdmin()) { Game.toast('Admin only - enter the admin code in the menu first.', true); return true; }
  if (c === 'help') {
    Game.banner('/tp house 1-20 | park | store | court | pond | swings | spawn   /time day|night|H   /doors open|close|auto   /party   /heal   /announce text');
    return true;
  }
  if (c === 'tp') {
    var a = (p[1] || '').toLowerCase(), s = null;
    if (a === 'house') { var n = Math.round(+p[2]); if (n >= 1 && n <= HOUSES.length) s = HOUSES[n - 1]; }
    else s = SPOTS[a];
    if (!s) { Game.toast('Usage: /tp house 1-20 | park | store | court | pond | swings | spawn', true); return true; }
    Game.tp(s[0], 14, s[1]); return true;
  }
  if (c === 'time') {
    var t = (p[1] || '').toLowerCase();
    var h = t === 'day' ? 12 : t === 'night' ? 0 : +t;
    if (t === '' || !isFinite(h)) { Game.toast('Usage: /time day|night|0-24', true); return true; }
    Game.setTime(h); Game.broadcast('time', { h: h }); Game.toast('Admin: time ' + h + ' for everyone'); return true;
  }
  if (c === 'doors') {
    var m = (p[1] || '').toLowerCase();
    if (m === 'close' || m === 'lock') m = 'locked';
    if (!Game.setDoors(m)) { Game.toast('Usage: /doors open|close|auto', true); return true; }
    Game.broadcast('doors', { m: m }); Game.toast('Admin: doors ' + m + ' for everyone'); return true;
  }
  if (c === 'party') { party(); Game.broadcast('party', {}); return true; }
  if (c === 'heal') { Game.heal(9999); Game.toast('Admin: healed'); return true; }
  if (c === 'announce') {
    var msg = text.slice(10).trim();
    if (!msg) { Game.toast('Usage: /announce message', true); return true; }
    Game.banner(msg); Game.broadcast('announce', { t: msg }); return true;
  }
  return false;
});
